PK3_BALLS = {1: "Master", 2: "Ultra", 3: "Great", 4: "Poke", 5: "Safari", 6: "Net", 7: "Dive", 8: "Nest",
             9: "Repeat", 10: "Timer", 11: "Luxury", 12: "Premier"}
PK3_MET_FATEFUL, PK3_MET_TRADE = 0xFF, 0xFE        # "met in a fateful encounter", an in-game trade
